package com.aistock.prediction.marketuse;

import com.aistock.common.marketlifecycle.*;
import com.aistock.common.marketlifecycle.MarketUseRecords.Selector;
import com.aistock.prediction.forecast.ForecastRepository;
import com.aistock.prediction.verification.VerificationRepository;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static com.aistock.prediction.maas.MaasOperationGate.*;

/** Durable owner registration for five-day forecasts and new actual-verification evidence. */
public final class PredictionMarketUseOwner {
 private record Binding(MarketUseClient.Request request,boolean started,MarketUseClient.Receipt receipt,boolean acked){}
 private final JdbcTemplate jdbc;private final ObjectMapper json;private final ForecastRepository forecasts;private final VerificationRepository verifications;private final MarketUseClient client;private final Clock clock;private final boolean forecastEnabled,verificationEnabled;private final TransactionTemplate tx;
 public PredictionMarketUseOwner(JdbcTemplate jdbc,ObjectMapper json,ForecastRepository forecasts,VerificationRepository verifications,MarketUseClient client,Clock clock,boolean forecastEnabled,boolean verificationEnabled){this.jdbc=jdbc;this.json=json;this.forecasts=forecasts;this.verifications=verifications;this.client=client;this.clock=clock;this.forecastEnabled=forecastEnabled;this.verificationEnabled=verificationEnabled;tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));tx.setTimeout(5);}
 public boolean enabled(String purpose){return switch(purpose){case "FORECAST"->forecastEnabled;case "PREDICTION_VERIFICATION"->verificationEnabled;default->false;};}
 private String source(String purpose,UUID op,long generation){return switch(purpose){case "FORECAST"->forecasts.marketUseInput(op,generation);case "PREDICTION_VERIFICATION"->verifications.marketUseInput(op,generation);default->throw MarketUseClient.invalid();};}
 public MarketUseContext.Scope acquire(String purpose,UUID op,long generation){
  if(!enabled(purpose))return MarketUseContext.empty();var b=prepare(purpose,op,generation);client.requireReady();
  if(b.receipt()==null){MarketUseClient.Receipt receipt;if(b.started())receipt=client.find(b.request()).orElseThrow(MarketUseClient::unavailable);else{if(start(purpose,op,generation))receipt=client.register(b.request());else receipt=client.find(b.request()).orElseThrow(MarketUseClient::unavailable);}attach(purpose,op,generation,receipt);b=read(purpose,op,generation);}
  return MarketUseContext.open(b.request(),b.receipt());
 }
 private Binding prepare(String purpose,UUID op,long generation){return tx.execute(s->{String stock=source(purpose,op,generation);var b=read(purpose,op,generation);if(b!=null){if(!b.request().selector().instruments().equals(List.of(stock)))throw MarketUseClient.invalid();return b;}jdbc.update("insert into prediction_market_use(owner_operation_id,purpose,execution_generation,request_id,instrument_id,created_at,last_checked_at) values(?,?,?,?,?,?,?)",op.toString(),purpose,generation,UUID.randomUUID().toString(),stock,ts(clock.instant()),ts(clock.instant()));return read(purpose,op,generation);});}
 private boolean start(String purpose,UUID op,long generation){return Boolean.TRUE.equals(tx.execute(s->{source(purpose,op,generation);return jdbc.update("update prediction_market_use set registration_started=true where owner_operation_id=? and purpose=? and execution_generation=? and registration_started=false",op.toString(),purpose,generation)==1;}));}
 private Binding read(String purpose,UUID op,long generation){var rows=jdbc.queryForList("select * from prediction_market_use where owner_operation_id=?",op.toString());if(rows.isEmpty())return null;var row=rows.get(0);if(!purpose.equals(row.get("purpose"))||generation<1||((Number)row.get("execution_generation")).longValue()!=generation)throw MarketUseClient.invalid();try{var request=new MarketUseClient.Request(op.toString(),Long.toString(generation),row.get("request_id").toString(),purpose,new Selector("CURRENT_HEADS",null,null,List.of(row.get("instrument_id").toString())));var receipt=row.get("receipt_json")==null?null:json.readValue(row.get("receipt_json").toString(),MarketUseClient.Receipt.class);if(receipt!=null&&(receipt.versionIds().size()!=1||!receipt.versionIds().get(0).equals(row.get("raw_version_id"))))throw MarketUseClient.invalid();return new Binding(request,Boolean.TRUE.equals(row.get("registration_started")),receipt,Boolean.TRUE.equals(row.get("completion_acked")));}catch(java.io.IOException e){throw MarketUseClient.invalid();}}
 private void attach(String purpose,UUID op,long generation,MarketUseClient.Receipt receipt){tx.executeWithoutResult(s->{jdbc.queryForMap("select * from prediction_market_use where owner_operation_id=? for update",op.toString());var b=read(purpose,op,generation);if(b==null||!b.started()||receipt.versionIds().size()!=1)throw MarketUseClient.invalid();if(b.receipt()!=null){if(!b.receipt().bundleId().equals(receipt.bundleId())||!b.receipt().versionIds().equals(receipt.versionIds()))throw MarketUseClient.invalid();return;}jdbc.update("update prediction_market_use set bundle_id=?,raw_version_id=?,receipt_json=? where owner_operation_id=? and purpose=? and execution_generation=? and bundle_id is null",receipt.bundleId(),receipt.versionIds().get(0),encode(receipt),op.toString(),purpose,generation);});}
 public JsonNode proof(String purpose,UUID op,String generation){long gen=MarketLifecycleContract.generation(generation);return tx.execute(s->{JsonNode state=switch(purpose){case "FORECAST"->forecasts.executionTerminal(op,gen);case "PREDICTION_VERIFICATION"->verifications.executionTerminal(op,gen);default->throw MarketUseClient.unavailable();};var b=read(purpose,op,gen);if(b==null||b.receipt()==null)throw MarketUseClient.unavailable();var n=((ObjectNode)state).deepCopy();n.put("owner","prediction").put("purpose",purpose).put("ownerOperationId",op.toString()).put("generation",generation);n.set("versionIds",json.valueToTree(b.receipt().versionIds()));return n;});}
 public void notifyCompleted(String purpose,UUID op,long generation){if(!enabled(purpose))return;try{var b=read(purpose,op,generation);if(b==null||b.receipt()==null||b.acked())return;proof(purpose,op,Long.toString(generation));mark(op,generation);var released=client.complete(b.request(),b.receipt());if(released==null||!"RELEASED".equals(released.state())||!b.receipt().bundleId().equals(released.bundleId())||!b.receipt().versionIds().equals(released.versionIds()))throw MarketUseClient.invalid();jdbc.update("update prediction_market_use set completion_acked=true where owner_operation_id=? and purpose=? and execution_generation=? and bundle_id=?",op.toString(),purpose,generation,b.receipt().bundleId());}catch(RuntimeException ignored){/* Persisted result and pending binding remain. */}}
 public void recoverOne(String purpose,UUID op,long generation){if(!enabled(purpose))return;try{mark(op,generation);var b=read(purpose,op,generation);if(b==null||!b.started()||b.acked())return;if(b.receipt()==null){var receipt=client.find(b.request());if(receipt.isEmpty())return;attach(purpose,op,generation,receipt.get());}notifyCompleted(purpose,op,generation);}catch(RuntimeException ignored){/* Unknown or malformed receipt is not a release or re-registration. */}}
 public void recoverBatch(){if(!forecastEnabled&&!verificationEnabled)return;var rows=jdbc.queryForList("select owner_operation_id,purpose,execution_generation from prediction_market_use where completion_acked=false and registration_started=true and ((purpose='FORECAST' and ?=true) or (purpose='PREDICTION_VERIFICATION' and ?=true)) order by last_checked_at,owner_operation_id limit 25",forecastEnabled,verificationEnabled);for(var r:rows)recoverOne(r.get("purpose").toString(),UUID.fromString(r.get("owner_operation_id").toString()),((Number)r.get("execution_generation")).longValue());}
 private void mark(UUID op,long generation){jdbc.update("update prediction_market_use set last_checked_at=greatest(?,timestampadd(microsecond,1000,last_checked_at)) where owner_operation_id=? and execution_generation=?",ts(clock.instant()),op.toString(),generation);}
 private String encode(Object value){try{return json.writeValueAsString(value);}catch(java.io.IOException e){throw MarketUseClient.invalid();}}
}
